// Test-fixture dependency for issues #92 and #93 — package identity inferred from a path.
//
// `forge-dep` holds NO grant of any kind in the fixture policy. Every capability it appears to
// hold below has been obtained by making capwall read a package name out of a path string.
//
// INERT (AGENTS.md § 8): the "secret" is a placeholder this test's own runner puts in the
// environment and in `secret.txt`; nothing here is a real payload and nothing leaves the
// process.
//
// TWO ROOT-CAUSE-IDENTICAL PRIMITIVES:
//   #92  ship a directory named after a granted package inside your own tree and run code from
//        it. The frames are ordinary and the file is real; capwall's path -> package rule reads
//        `forge-target` out of `…/forge-dep/node_modules/forge-target/vendored.cjs`.
//   #93  `Module.prototype._compile(source, filename)` compiles code with a CALLER-CHOSEN
//        filename, and V8 reports it as `getFileName()` on every resulting frame. `isEval()` is
//        false, there is no eval origin, and the path need not even exist.

const path = require("node:path");
const Module = require("node:module");

const SECRET = "FORGE_FIXTURE_SECRET";
const FIXTURE_ROOT = path.join(__dirname, "..", "..");
const SECRET_FILE = path.join(FIXTURE_ROOT, "secret.txt");

/** Real, installed path of the one top-level package the fixture policy grants. */
const TARGET_PATH = path.join(__dirname, "..", "forge-target", "index.cjs");
/** A real application source file — anything outside `node_modules` resolves to `<app>`. */
const APP_PATH = path.join(FIXTURE_ROOT, "app.cjs");
/** A path inside `forge-dep`'s OWN tree — compiling here gains no identity it does not have. */
const SELF_PATH = path.join(__dirname, "generated.cjs");

/**
 * The two capability calls every vector performs, as a SOURCE STRING for the `_compile`
 * vectors. `require` resolves through the CJS wrapper `_compile` builds, so the compiled
 * module gets a working `require` exactly as an ordinary module would.
 */
const PAYLOAD = `module.exports = function compiledPayload() {
  const out = { env: process.env[${JSON.stringify(SECRET)}], fs: undefined };
  try {
    out.fs = require("node:fs").readFileSync(${JSON.stringify(SECRET_FILE)}, "utf8").trim();
  } catch (err) {
    out.fs = err && err.name === "CapabilityError" ? "DENIED:" + err.pkg : "THREW:" + err.message;
  }
  return out;
};`;

/**
 * The #93 primitive, verbatim from the issue: build a `Module` by hand, hand `_compile` a
 * filename of our choosing, and run what comes out. Every frame inside the compiled function
 * reports `filename` from `getFileName()`.
 */
function compileAs(filename) {
  const m = new Module(filename, module);
  m.filename = filename;
  m.paths = module.paths;
  try {
    m._compile(PAYLOAD, filename);
  } catch (err) {
    // After the fix the COMPILE itself is the gated event, so report it in the same shape the
    // capability calls use — the test asserts on the principal either way.
    return err && err.name === "CapabilityError"
      ? { env: undefined, fs: `COMPILEDENIED:${err.pkg}` }
      : { env: undefined, fs: `THREW:${err.message}` };
  }
  return m.exports();
}

const VECTORS = {
  /** Control: `forge-dep` calling honestly, from its own ordinary frames. Must be denied. */
  honest: () => {
    const out = { env: process.env[SECRET], fs: undefined };
    try {
      out.fs = require("node:fs").readFileSync(SECRET_FILE, "utf8").trim();
    } catch (err) {
      out.fs = err && err.name === "CapabilityError" ? `DENIED:${err.pkg}` : `THREW:${err.message}`;
    }
    return out;
  },

  /** #92, the issue's PoC: run attacker-authored code from a vendored `forge-target` dir. */
  vendored: () => require("./node_modules/forge-target/vendored.cjs")(),

  /** #92 variant: a fake pnpm virtual store shipped inside `forge-dep`'s own tree. */
  "vendored-pnpm": () =>
    require("./node_modules/.pnpm/forge-target@1.0.0/node_modules/forge-target/store.cjs")(),

  /** #93, the issue's PoC: name the real installed file of the one granted package. */
  compile: () => compileAs(TARGET_PATH),

  /**
   * #93 variant: name a file outside `node_modules`, which resolves to `<app>` — the trust
   * root, whose `process.env` reads the env shim exempts BEFORE the decision is recorded, so a
   * successful forgery here is invisible to `observe` and `capwall diff` as well.
   */
  "compile-app": () => compileAs(APP_PATH),

  /** #93 variant: the named path need not exist. Nothing ever reads it. */
  "compile-ghost": () =>
    compileAs(path.join(__dirname, "..", "forge-target", "does-not-exist.cjs")),

  /**
   * LEGITIMATE USE, pinned deliberately. A package compiling its own generated source under
   * its OWN name gains no identity it did not already have, so the gate lets it through with
   * no grant at all. (`generated.cjs` does not exist on disk — that is the point: this is the
   * `require-from-string` / template-engine shape, where the filename is a label.)
   */
  "compile-self": () => compileAs(SELF_PATH),

  /**
   * BOOTSTRAP ATTACK on the gate itself. The gate lets Node's own loader through by checking
   * whether `_compile`'s immediate caller frame reports a `node:internal/modules/…` file name.
   * The obvious counter is to MANUFACTURE such a frame — compile a payload under that very
   * name, then call `_compile` again from inside it, where the discriminator now sees a
   * `node:internal/…` caller and waves it past.
   *
   * The first hop has to succeed for the second to exist, and it does not: a non-absolute
   * filename is never treated as the caller's own package, so this is evaluated against the
   * policy like any other foreign filename and denied. Pinned because the gate's safety rests
   * on it.
   */
  "compile-nodename": () => compileAs("node:internal/modules/cjs/loader"),
};

async function run(vector) {
  const fn = VECTORS[vector];
  if (fn === undefined) throw new Error(`unknown vector: ${vector}`);
  return await fn();
}

module.exports = { run, VECTORS: Object.keys(VECTORS) };
